from typing import List, Tuple

def f(N: int, A: List[Tuple[str, int]], M: int, O: List[str]):
    '''
    N: an integer
    A: a list of tuples, where each tuple contains a string and an integer
    M: an integer
    O: a list of strings
    ''' 
    # Create a dictionary to store the area for each color
    area_dict = {}
    for color, area in A:
        if color not in area_dict:
            area_dict[color] = 0
        area_dict[color] += area

    # Process each query
    results = []
    for query in O:
        color = query
        if color in area_dict:
            results.append(area_dict[color])
        else:
            results.append(0)

    return '\n'.join(map(str, results))
```
